        _, depth, _, node, prefix = heapq.heappop(heap)
        expanded += 1
        if depth >= max_depth:
            continue
        for action in candidate_actions(node):
            child = node.clone()
            try:
                child.step(*action)
            except Exception:
                continue
            child_path = prefix + [action]
            if child.levels_completed > start_level:
                path = child_path
                heap = []
                break
            movable, child_avatar, child_compact = state(child)
            if (
                child.terminal()
                or sum(mass for _, mass, _ in movable) != initial_mass
            ):
                continue
            key = (child_compact, child_avatar)
            if key in seen:
                continue
            seen.add(key)
            heapq.heappush(
                heap,
                (
                    priority(child, len(child_path)),
                    len(child_path),
                    next(serial),
                    child,
                    child_path,
                ),
            )

    if path is None:
        return
    for action in path:
        if env.terminal() or env.levels_completed != start_level:
            return
        env.step(*action)


import players

def solve(env):
    # dispatch to the per-level player for the current level, in a loop
    while not env.terminal():
        k = env.levels_completed + 1
        fn = getattr(players, f'play_level_{k}', None)
        if fn is None:
            return
        before = env.levels_completed
        fn(env)
        if env.levels_completed <= before:
            return  # no progress -> stop
